'use strict';

// MODULES //

var isSameValue = require( '@stdlib/assert/is-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var min = require( '@stdlib/math/base/special/fast/min' );


// MAIN //

/**
* Returns the index of the first element at which two arrays differ.
*
* ## Notes
*
* -   When `strict` is `true`, the function compares elements using the SameValue algorithm (i.e., `NaN` equals `NaN`, and `-0` and `+0` are distinguished). Otherwise, the function compares elements using strict equality, except that `NaN` equals `NaN` (i.e., signed zeros are not distinguished).
* -   When the arrays have different lengths, the function returns the length of the shorter array, unless the arrays differ at a smaller index.
*
* @private
* @param {Collection} x - first array
* @param {Collection} y - second array
* @param {boolean} strict - boolean indicating whether to distinguish signed zeros
* @returns {integer} index of the first difference, or `-1` if the arrays are identical
*/
function firstDifference( x, y, strict ) {
	var len;
	var i;

	len = min( x.length, y.length );
	for ( i = 0; i < len; i++ ) {
		if ( strict ) {
			if ( !isSameValue( x[ i ], y[ i ] ) ) {
				return i;
			}
		} else if ( x[ i ] !== y[ i ] ) {
			if ( !isnan( x[ i ] ) || !isnan( y[ i ] ) ) {
				return i;
			}
		}
	}
	if ( x.length === y.length ) {
		return -1;
	}
	return len;
}


// EXPORTS //

module.exports = firstDifference;
